import{_ as t,o as a,c as i,a2 as n}from"./chunks/framework.Cm6XCzck.js";const u=JSON.parse('{"title":"Research Runtime Center V4","description":"","frontmatter":{"title":"Research Runtime Center V4","outline":"deep"},"headers":[],"relativePath":"en/runtime/v4.md","filePath":"en/runtime/v4.md","lastUpdated":1785823690000}'),s={name:"en/runtime/v4.md"};function r(l,e,o,c,d,p){return a(),i("div",null,[...e[0]||(e[0]=[n(`<h1 id="research-runtime-center-v4" tabindex="-1">Research Runtime Center V4 <a class="header-anchor" href="#research-runtime-center-v4" aria-label="Permalink to &quot;Research Runtime Center V4&quot;">​</a></h1><h2 id="definition" tabindex="-1">Definition <a class="header-anchor" href="#definition" aria-label="Permalink to &quot;Definition&quot;">​</a></h2><p>Research Runtime Center V4 is the Digital Researcher’s operations center: three research-intelligence pipelines jointly discover evidence for the three columns, morning shifts advance research, the afternoon shift produces complete reports, and the evening shift releases them through GitHub and the website.</p><h2 id="research-intelligence-system" tabindex="-1">Research Intelligence System <a class="header-anchor" href="#research-intelligence-system" aria-label="Permalink to &quot;Research Intelligence System&quot;">​</a></h2><p>Where evidence is discovered and what the Research Center studies are separate dimensions.</p><h3 id="three-source-intelligence-pipelines" tabindex="-1">Three source-intelligence pipelines <a class="header-anchor" href="#three-source-intelligence-pipelines" aria-label="Permalink to &quot;Three source-intelligence pipelines&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Skill 01-P — AI Platform Change Intelligence</span></span>
<span class="line"><span>Skill 01-G — GitHub Engineering Intelligence</span></span>
<span class="line"><span>Skill 01-R — Published Research Intelligence</span></span></code></pre></div><p>The pipelines produce one unified, deduplicated signal pool before Skill 02 performs three-column research triage.</p><h3 id="p0-ai-platform-coverage" tabindex="-1">P0 AI platform coverage <a class="header-anchor" href="#p0-ai-platform-coverage" aria-label="Permalink to &quot;P0 AI platform coverage&quot;">​</a></h3><p>The daily platform set is fixed:</p><ul><li>OpenAI / ChatGPT / Codex;</li><li>Anthropic / Claude / Claude Code;</li><li>Google / Gemini;</li><li>Cursor;</li><li>GitHub Copilot;</li><li>Microsoft Copilot Platform.</li></ul><p>The worker checks official release notes, documentation, forums or communities, official GitHub sources, status pages, enterprise controls, permissions, and product boundaries. Authentication-required channels must be recorded as restricted rather than reported as checked with no update.</p><h3 id="github-engineering-radar" tabindex="-1">GitHub engineering radar <a class="header-anchor" href="#github-engineering-radar" aria-label="Permalink to &quot;GitHub engineering radar&quot;">​</a></h3><p>GitHub is not scanned platform-wide. The governed radar uses:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>70% fixed organization and repository watchlist</span></span>
<span class="line"><span>20% versioned topic × change-type queries</span></span>
<span class="line"><span>10% bounded new-project exploration</span></span></code></pre></div><p>It inspects incremental Releases, Tags, merged PRs, high-value Issues, Discussions, Security Advisories, and architecture, test, and benchmark files.</p><h3 id="published-research-radar" tabindex="-1">Published research radar <a class="header-anchor" href="#published-research-radar" aria-label="Permalink to &quot;Published research radar&quot;">​</a></h3><p>The system observes papers, preprints, technical reports, benchmarks, datasets, system and model cards, specifications, and associated code or evaluation artifacts. An abstract or vendor summary alone cannot establish an engineering conclusion.</p><p><a href="/joinwell52/en/runtime/research-intelligence">Read Research Intelligence System V1.0</a></p><h2 id="three-research-columns" tabindex="-1">Three research columns <a class="header-anchor" href="#three-research-columns" aria-label="Permalink to &quot;Three research columns&quot;">​</a></h2><p>At 10:00, Research Runtime Queue must make a separate decision for each column:</p><ol><li><strong>Digital Employee</strong> — positions, responsibilities, workflows, runtime, governance, recovery, delivery, and evaluation;</li><li><strong>Industry Architecture</strong> — major AI platform products, workspaces, Agent operating models, control planes, permissions, connectors, enterprise controls, and product boundaries;</li><li><strong>Open-source Engineering</strong> — open-source runtimes, protocols, SDKs, tools, benchmarks, recovery, testing, and observability engineering.</li></ol><p>Every column must show:</p><ul><li>today’s selected topic, or <code>No Selection</code>;</li><li>the reason for selection or non-selection;</li><li>the primary source;</li><li>priority and lifecycle state;</li><li>the next governed action.</li></ul><h2 id="daily-shifts" tabindex="-1">Daily shifts <a class="header-anchor" href="#daily-shifts" aria-label="Permalink to &quot;Daily shifts&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Time</th><th>Shift</th><th>Work outcome</th></tr></thead><tbody><tr><td>09:00</td><td>Research Runtime Engine</td><td>Advance exactly one governed lifecycle transition.</td></tr><tr><td>10:00</td><td>Research Runtime Queue</td><td>Execute the three intelligence pipelines, deduplicate evidence, score candidates, and publish the three-column research plan.</td></tr><tr><td>11:00</td><td>Research Runtime Knowledge</td><td>Admit qualified Research Notes into Knowledge and maintain architecture candidates.</td></tr><tr><td>15:00</td><td><strong>Research Runtime Production</strong></td><td>Complete bilingual reports, visualization, citations, and publication editing, producing Publication Candidates.</td></tr><tr><td>20:00</td><td>Research Runtime Publication</td><td>Release complete candidates, update indexes and the website, commit to GitHub, and verify the commit.</td></tr></tbody></table><p>Monday also includes Architecture at 12:00; Sunday includes Weekly at 20:30; Wednesday includes Academic at 10:00.</p><h2 id="the-10-00-intelligence-and-selection-shift" tabindex="-1">The 10:00 intelligence and selection shift <a class="header-anchor" href="#the-10-00-intelligence-and-selection-shift" aria-label="Permalink to &quot;The 10:00 intelligence and selection shift&quot;">​</a></h2><p>Queue completion no longer means that one news item was found. It requires:</p><ul><li>a coverage result for all three intelligence pipelines;</li><li>every due source checked, explicitly restricted, or failed with a reason;</li><li>cross-source deduplication of the same platform, GitHub, and research change;</li><li>exactly one primary column for every selected object;</li><li>a <code>Selected</code> or <code>No Selection</code> decision for every column;</li><li>matching selected IDs between the Intelligence run and the Daily Research Plan.</li></ul><h2 id="the-15-00-production-shift" tabindex="-1">The 15:00 Production shift <a class="header-anchor" href="#the-15-00-production-shift" aria-label="Permalink to &quot;The 15:00 Production shift&quot;">​</a></h2><p>The afternoon shift invokes the existing Research Skills:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Skill 05 — Research Writing</span></span>
<span class="line"><span>→ Skill 06 — Visualization</span></span>
<span class="line"><span>→ Skill 07 — Evidence &amp; Citation</span></span>
<span class="line"><span>→ Skill 08 — Publication Editing</span></span></code></pre></div><p>Its output is not a partial draft. It is a complete <strong>Publication Candidate</strong>:</p><ul><li>complete Chinese Markdown;</li><li>complete English Markdown;</li><li>valid metadata and column assignment;</li><li>completed visualization, or an explicit decision that no visual is required;</li><li>verified evidence and citations;</li><li>completed publication editing;</li><li>not yet placed in the public article directory.</li></ul><h2 id="the-20-00-release-shift" tabindex="-1">The 20:00 release shift <a class="header-anchor" href="#the-20-00-release-shift" aria-label="Permalink to &quot;The 20:00 release shift&quot;">​</a></h2><p>The evening shift releases only; it does not restart research or writing:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Publication Candidate</span></span>
<span class="line"><span>→ public bilingual articles</span></span>
<span class="line"><span>→ metadata / indexes / website</span></span>
<span class="line"><span>→ GitHub Commit</span></span>
<span class="line"><span>→ Commit Verify</span></span>
<span class="line"><span>→ Release</span></span></code></pre></div><p>A candidate that fails the release gate returns to Production or an earlier research stage.</p><h2 id="four-authoritative-runtime-artifacts" tabindex="-1">Four authoritative runtime artifacts <a class="header-anchor" href="#four-authoritative-runtime-artifacts" aria-label="Permalink to &quot;Four authoritative runtime artifacts&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>research/runtime/YYYY/MM/YYYY-MM-DD-runtime.md</span></span></code></pre></div><p>Records each shift’s status, input, work outcome, output, next action, and GitHub evidence.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>research/intelligence/runs/YYYY/MM/YYYY-MM-DD-intelligence.json</span></span></code></pre></div><p>Records coverage, failures, signals, candidates, and three-column triage decisions for all intelligence pipelines.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>research/runtime/plans/YYYY/MM/YYYY-MM-DD-plan.json</span></span></code></pre></div><p>Records the daily topic decision for all three columns and must agree with the Intelligence run.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>research/runtime/candidates/YYYY/MM/YYYY-MM-DD-candidates.json</span></span></code></pre></div><p>Records the complete Publication Candidates produced at 15:00 and consumed at 20:00.</p><h2 id="completion-rate" tabindex="-1">Completion rate <a class="header-anchor" href="#completion-rate" aria-label="Permalink to &quot;Completion rate&quot;">​</a></h2><p>Only <code>Completed</code> counts toward completion:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>completion rate = Completed scheduled tasks ÷ all scheduled tasks</span></span></code></pre></div><p><code>Waiting</code> and <code>Running</code> are unfinished. <code>Skipped</code>, <code>Blocked</code>, and <code>Failed</code> are terminal but not complete.</p><h2 id="governing-principles" tabindex="-1">Governing principles <a class="header-anchor" href="#governing-principles" aria-label="Permalink to &quot;Governing principles&quot;">​</a></h2><blockquote><p>All three intelligence pipelines serve all three research columns.</p></blockquote><blockquote><p>Checked with no important change and not checked are different facts.</p></blockquote><blockquote><p>Every scheduled task must report its actual work outcome, not merely that it ran.</p></blockquote><blockquote><p>The afternoon shift produces the complete report; the evening shift performs release only.</p></blockquote><blockquote><p>A publication without a Runtime Record and Commit Verify is not an official runtime output.</p></blockquote>`,58)])])}const m=t(s,[["render",r]]);export{u as __pageData,m as default};
